// Dhikr and doa texts for Tahlil and Al-Ma'thurat Sughra.
// These are standard hadith-based adhkar and the usual Malaysian Tahlil sequence.
// Checked and verified by an ustaz.
export type ZT = { ar: string; rumi: string; ms: string; en: string };
export const ZTEXT: Record<string, { m: ZT; e?: ZT; more?: ZT[] }> = {
  "Ta'awwudh": { m: { ar: 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ', rumi: "A'udzu billahi minash-shaitanir-rajim.", ms: 'Aku berlindung dengan Allah daripada syaitan yang direjam.', en: 'I seek refuge in Allah from the accursed Satan.' } },
  'Doa: Asbahna / Amsaina wa amsal-mulku lillah': {
    m: { ar: 'أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلّٰهِ وَالْحَمْدُ لِلّٰهِ، لَا إِلٰهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هٰذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هٰذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ', rumi: "Asbahna wa asbahal-mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la syarika lah, lahul-mulku wa lahul-hamdu wa huwa 'ala kulli syai'in qadir. Rabbi as'aluka khaira ma fi hazal-yaumi wa khaira ma ba'dah, wa a'udzu bika min syarri ma fi hazal-yaumi wa syarri ma ba'dah. Rabbi a'udzu bika minal-kasali wa su'il-kibar. Rabbi a'udzu bika min 'azabin fin-nar wa 'azabin fil-qabr.", ms: 'Kami berpagi-pagi dan kerajaan berpagi-pagi milik Allah. Segala puji bagi Allah. Tiada Tuhan selain Allah Yang Esa, tiada sekutu bagi-Nya. Bagi-Nya kerajaan dan bagi-Nya segala puji, dan Dia Maha Berkuasa atas segala sesuatu. Wahai Tuhanku, aku memohon kebaikan hari ini dan kebaikan selepasnya, dan aku berlindung daripada kejahatan hari ini dan kejahatan selepasnya. Wahai Tuhanku, aku berlindung daripada kemalasan dan buruknya usia tua. Wahai Tuhanku, aku berlindung daripada azab di neraka dan azab di kubur.', en: 'We have reached the morning and the dominion belongs to Allah. Praise is for Allah. There is no god but Allah alone, without partner. His is the dominion and His is the praise, and He is able to do all things. My Lord, I ask You for the good of this day and the good after it, and I seek refuge in You from the evil of this day and the evil after it. My Lord, I seek refuge in You from laziness and the evil of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave.' },
    e: { ar: 'أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلّٰهِ وَالْحَمْدُ لِلّٰهِ، لَا إِلٰهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هٰذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هٰذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ', rumi: "Amsaina wa amsal-mulku lillah, walhamdu lillah, la ilaha illallahu wahdahu la syarika lah, lahul-mulku wa lahul-hamdu wa huwa 'ala kulli syai'in qadir. Rabbi as'aluka khaira ma fi hazihil-lailati wa khaira ma ba'daha, wa a'udzu bika min syarri ma fi hazihil-lailati wa syarri ma ba'daha. Rabbi a'udzu bika minal-kasali wa su'il-kibar. Rabbi a'udzu bika min 'azabin fin-nar wa 'azabin fil-qabr.", ms: 'Kami berpetang-petang dan kerajaan berpetang-petang milik Allah. Segala puji bagi Allah. Tiada Tuhan selain Allah Yang Esa, tiada sekutu bagi-Nya. Bagi-Nya kerajaan dan bagi-Nya segala puji, dan Dia Maha Berkuasa atas segala sesuatu. Wahai Tuhanku, aku memohon kebaikan malam ini dan kebaikan selepasnya, dan aku berlindung daripada kejahatan malam ini dan kejahatan selepasnya. Wahai Tuhanku, aku berlindung daripada kemalasan dan buruknya usia tua. Wahai Tuhanku, aku berlindung daripada azab di neraka dan azab di kubur.', en: 'We have reached the evening and the dominion belongs to Allah. Praise is for Allah. There is no god but Allah alone, without partner. His is the dominion and His is the praise, and He is able to do all things. My Lord, I ask You for the good of this night and the good after it, and I seek refuge in You from the evil of this night and the evil after it. My Lord, I seek refuge in You from laziness and the evil of old age. My Lord, I seek refuge in You from punishment in the Fire and punishment in the grave.' },
  },
  'Doa: Asbahna / Amsaina, firm upon Islam': {
    m: { ar: 'أَصْبَحْنَا عَلَىٰ فِطْرَةِ الْإِسْلَامِ، وَعَلَىٰ كَلِمَةِ الْإِخْلَاصِ، وَعَلَىٰ دِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَعَلَىٰ مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ', rumi: "Asbahna 'ala fitratil-Islam, wa 'ala kalimatil-ikhlas, wa 'ala dini nabiyyina Muhammadin sallallahu 'alaihi wa sallam, wa 'ala millati abina Ibrahima hanifan musliman wa ma kana minal-musyrikin.", ms: 'Kami berpagi-pagi di atas fitrah Islam, kalimah ikhlas, agama Nabi kami Muhammad ﷺ dan agama bapa kami Ibrahim yang lurus lagi berserah diri, dan dia bukanlah daripada golongan musyrikin.', en: 'We have reached the morning upon the natural religion of Islam, the word of sincerity, the religion of our Prophet Muhammad ﷺ and the creed of our father Ibrahim, upright and submitting, and he was not of the polytheists.' },
    e: { ar: 'أَمْسَيْنَا عَلَىٰ فِطْرَةِ الْإِسْلَامِ، وَعَلَىٰ كَلِمَةِ الْإِخْلَاصِ، وَعَلَىٰ دِينِ نَبِيِّنَا مُحَمَّدٍ ﷺ، وَعَلَىٰ مِلَّةِ أَبِينَا إِبْرَاهِيمَ حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ', rumi: "Amsaina 'ala fitratil-Islam, wa 'ala kalimatil-ikhlas, wa 'ala dini nabiyyina Muhammadin sallallahu 'alaihi wa sallam, wa 'ala millati abina Ibrahima hanifan musliman wa ma kana minal-musyrikin.", ms: 'Kami berpetang-petang di atas fitrah Islam, kalimah ikhlas, agama Nabi kami Muhammad ﷺ dan agama bapa kami Ibrahim yang lurus lagi berserah diri, dan dia bukanlah daripada golongan musyrikin.', en: 'We have reached the evening upon the natural religion of Islam, the word of sincerity, the religion of our Prophet Muhammad ﷺ and the creed of our father Ibrahim, upright and submitting, and he was not of the polytheists.' },
  },
  'Doa: Allahumma inni asbahtu / amsaytu': {
    m: { ar: 'اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ أَنَّكَ أَنْتَ اللهُ لَا إِلٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ', rumi: "Allahumma inni asbahtu usyhiduka wa usyhidu hamalata 'arsyika wa mala'ikataka wa jami'a khalqika annaka antallahu la ilaha illa anta wahdaka la syarika lak, wa anna Muhammadan 'abduka wa rasuluk.", ms: 'Ya Allah, sesungguhnya aku berpagi-pagi menjadikan Engkau saksi, dan menjadikan penanggung Arasy-Mu, malaikat-Mu dan seluruh makhluk-Mu sebagai saksi, bahawa Engkaulah Allah, tiada Tuhan selain Engkau Yang Esa, tiada sekutu bagi-Mu, dan bahawa Muhammad ialah hamba-Mu dan utusan-Mu.', en: 'O Allah, I have reached the morning calling You to witness, and calling the bearers of Your Throne, Your angels and all Your creation to witness, that You are Allah, there is no god but You alone, without partner, and that Muhammad is Your servant and Messenger.' },
    e: { ar: 'اللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ أَنَّكَ أَنْتَ اللهُ لَا إِلٰهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ', rumi: "Allahumma inni amsaytu usyhiduka wa usyhidu hamalata 'arsyika wa mala'ikataka wa jami'a khalqika annaka antallahu la ilaha illa anta wahdaka la syarika lak, wa anna Muhammadan 'abduka wa rasuluk.", ms: 'Ya Allah, sesungguhnya aku berpetang-petang menjadikan Engkau saksi, dan menjadikan penanggung Arasy-Mu, malaikat-Mu dan seluruh makhluk-Mu sebagai saksi, bahawa Engkaulah Allah, tiada Tuhan selain Engkau Yang Esa, tiada sekutu bagi-Mu, dan bahawa Muhammad ialah hamba-Mu dan utusan-Mu.', en: 'O Allah, I have reached the evening calling You to witness, and calling the bearers of Your Throne, Your angels and all Your creation to witness, that You are Allah, there is no god but You alone, without partner, and that Muhammad is Your servant and Messenger.' },
  },
  'Doa: Allahumma ma asbaha / ma amsa': {
    m: { ar: 'اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ', rumi: "Allahumma ma asbaha bi min ni'matin au bi ahadin min khalqika faminka wahdaka la syarika lak, falakal-hamdu wa lakasy-syukr.", ms: 'Ya Allah, apa jua nikmat yang ada pada diriku atau pada seseorang daripada makhluk-Mu pada pagi ini, ia datang daripada-Mu semata-mata, tiada sekutu bagi-Mu. Bagi-Mu segala puji dan bagi-Mu segala kesyukuran.', en: 'O Allah, whatever blessing has come to me or to any of Your creation this morning is from You alone, without partner. So to You is the praise and to You is the thanks.' },
    e: { ar: 'اللَّهُمَّ مَا أَمْسَىٰ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ', rumi: "Allahumma ma amsa bi min ni'matin au bi ahadin min khalqika faminka wahdaka la syarika lak, falakal-hamdu wa lakasy-syukr.", ms: 'Ya Allah, apa jua nikmat yang ada pada diriku atau pada seseorang daripada makhluk-Mu pada petang ini, ia datang daripada-Mu semata-mata, tiada sekutu bagi-Mu. Bagi-Mu segala puji dan bagi-Mu segala kesyukuran.', en: 'O Allah, whatever blessing has come to me or to any of Your creation this evening is from You alone, without partner. So to You is the praise and to You is the thanks.' },
  },
  'Doa: Ya Rabbi lakal-hamdu': { m: { ar: 'يَا رَبِّ لَكَ الْحَمْدُ كَمَا يَنْبَغِي لِجَلَالِ وَجْهِكَ وَعَظِيمِ سُلْطَانِكَ', rumi: "Ya Rabbi lakal-hamdu kama yanbaghi lijalali wajhika wa 'azimi sultanik.", ms: 'Wahai Tuhanku, bagi-Mu segala puji sebagaimana layak bagi kemuliaan Zat-Mu dan keagungan kekuasaan-Mu.', en: 'O my Lord, to You is praise as befits the majesty of Your Face and the greatness of Your authority.' } },
  'Radhitu billahi Rabban': { m: { ar: 'رَضِيتُ بِاللهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ ﷺ نَبِيًّا وَرَسُولًا', rumi: "Radhitu billahi Rabba, wa bil-Islami dina, wa bi Muhammadin sallallahu 'alaihi wa sallam nabiyyan wa rasula.", ms: 'Aku reda Allah sebagai Tuhan, Islam sebagai agama, dan Muhammad ﷺ sebagai nabi dan rasul.', en: 'I am pleased with Allah as Lord, Islam as religion, and Muhammad ﷺ as Prophet and Messenger.' } },
  'Subhanallahi wa bihamdihi': { m: { ar: 'سُبْحَانَ اللهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ وَرِضَا نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ', rumi: "Subhanallahi wa bihamdihi, 'adada khalqihi wa rida nafsihi wa zinata 'arsyihi wa midada kalimatih.", ms: 'Maha Suci Allah dan dengan memuji-Nya, sebanyak bilangan makhluk-Nya, sebanyak keredaan-Nya, seberat Arasy-Nya dan sebanyak tinta kalimah-Nya.', en: 'Glory be to Allah and praise to Him, as many as the number of His creation, as much as pleases Him, as heavy as His Throne and as vast as the ink of His words.' } },
  'Bismillahil-lazi la yadurru': { m: { ar: 'بِسْمِ اللهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ', rumi: "Bismillahil-ladzi la yadurru ma'asmihi syai'un fil-ardi wa la fis-sama'i wa huwas-sami'ul-'alim.", ms: 'Dengan nama Allah yang bersama nama-Nya tiada sesuatu pun di bumi dan di langit yang dapat memudaratkan, dan Dia Maha Mendengar lagi Maha Mengetahui.', en: 'In the name of Allah, with whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, the All-Knowing.' } },
  "Allahumma inna na'udzu bika (from shirk)": { m: { ar: 'اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نُشْرِكَ بِكَ شَيْئًا نَعْلَمُهُ، وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُهُ', rumi: "Allahumma inna na'udzu bika min an nusyrika bika syai'an na'lamuh, wa nastaghfiruka lima la na'lamuh.", ms: 'Ya Allah, kami berlindung dengan-Mu daripada menyekutukan-Mu dengan sesuatu yang kami ketahui, dan kami memohon ampun kepada-Mu daripada apa yang tidak kami ketahui.', en: 'O Allah, we seek refuge in You from associating anything with You knowingly, and we ask Your forgiveness for what we do not know.' } },
  "A'udzu bi kalimatillahit-tammat": { m: { ar: 'أَعُوذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ', rumi: "A'udzu bikalimatillahit-tammati min syarri ma khalaq.", ms: 'Aku berlindung dengan kalimah-kalimah Allah yang sempurna daripada kejahatan apa yang Dia ciptakan.', en: 'I seek refuge in the perfect words of Allah from the evil of what He has created.' } },
  'Doa: refuge from worry, sadness and debt': { m: { ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ', rumi: "Allahumma inni a'udzu bika minal-hammi wal-hazan, wa a'udzu bika minal-'ajzi wal-kasal, wa a'udzu bika minal-jubni wal-bukhl, wa a'udzu bika min ghalabatid-daini wa qahrir-rijal.", ms: 'Ya Allah, aku berlindung dengan-Mu daripada kerisauan dan kesedihan, daripada kelemahan dan kemalasan, daripada sifat pengecut dan bakhil, dan daripada bebanan hutang serta penindasan manusia.', en: 'O Allah, I seek refuge in You from worry and sadness, from weakness and laziness, from cowardice and stinginess, and from being overcome by debt and overpowered by men.' } },
  'Doa: Allahumma afini fi badani': { m: { ar: 'اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لَا إِلٰهَ إِلَّا أَنْتَ', rumi: "Allahumma 'afini fi badani, Allahumma 'afini fi sam'i, Allahumma 'afini fi basari, la ilaha illa anta.", ms: 'Ya Allah, sihatkanlah tubuh badanku. Ya Allah, sihatkanlah pendengaranku. Ya Allah, sihatkanlah penglihatanku. Tiada Tuhan selain Engkau.', en: 'O Allah, grant me well-being in my body. O Allah, grant me well-being in my hearing. O Allah, grant me well-being in my sight. There is no god but You.' } },
  'Doa: refuge from disbelief and poverty': { m: { ar: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلٰهَ إِلَّا أَنْتَ', rumi: "Allahumma inni a'udzu bika minal-kufri wal-faqr, wa a'udzu bika min 'azabil-qabr, la ilaha illa anta.", ms: 'Ya Allah, aku berlindung dengan-Mu daripada kekufuran dan kefakiran, dan aku berlindung dengan-Mu daripada azab kubur. Tiada Tuhan selain Engkau.', en: 'O Allah, I seek refuge in You from disbelief and poverty, and I seek refuge in You from the punishment of the grave. There is no god but You.' } },
  'Sayyidul Istighfar: Allahumma anta Rabbi': { m: { ar: 'اللَّهُمَّ أَنْتَ رَبِّي لَا إِلٰهَ إِلَّا أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَىٰ عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ', rumi: "Allahumma anta Rabbi la ilaha illa anta, khalaqtani wa ana 'abduka, wa ana 'ala 'ahdika wa wa'dika mastata'tu, a'udzu bika min syarri ma shana'tu, abu'u laka bini'matika 'alayya, wa abu'u bizanbi faghfir li fa innahu la yaghfiruz-zunuba illa anta.", ms: 'Ya Allah, Engkaulah Tuhanku, tiada Tuhan selain Engkau. Engkau menciptakan aku dan aku hamba-Mu. Aku berpegang pada janji-Mu sedaya upayaku. Aku berlindung dengan-Mu daripada kejahatan perbuatanku. Aku mengakui nikmat-Mu ke atasku dan aku mengakui dosaku, maka ampunilah aku, kerana tiada yang mengampuni dosa melainkan Engkau.', en: 'O Allah, You are my Lord, there is no god but You. You created me and I am Your servant, and I keep Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins but You.' } },
  'Astaghfirullahal-lazi': { m: { ar: 'أَسْتَغْفِرُ اللهَ الْعَظِيمَ الَّذِي لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ', rumi: "Astaghfirullahal-'azimal-ladzi la ilaha illa huwal-hayyul-qayyumu wa atubu ilaih.", ms: 'Aku memohon ampun kepada Allah Yang Maha Agung, yang tiada Tuhan selain Dia, Yang Maha Hidup lagi Maha Berdiri Sendiri, dan aku bertaubat kepada-Nya.', en: 'I ask forgiveness of Allah the Almighty, there is no god but He, the Ever-Living, the Sustainer, and I repent to Him.' } },
  'Subhanaka Allahumma wa bihamdika': { m: { ar: 'سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلٰهَ إِلَّا أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ', rumi: "Subhanakallahumma wa bihamdika, asyhadu an la ilaha illa anta, astaghfiruka wa atubu ilaik.", ms: 'Maha Suci Engkau ya Allah dan dengan memuji-Mu. Aku bersaksi bahawa tiada Tuhan selain Engkau. Aku memohon ampun kepada-Mu dan bertaubat kepada-Mu.', en: 'Glory and praise be to You, O Allah. I bear witness that there is no god but You. I seek Your forgiveness and repent to You.' } },
  // Tahlil
  'Opening dedication (Ayat Pembuka)': { m: { ar: 'إِلَىٰ حَضْرَةِ النَّبِيِّ الْمُصْطَفَىٰ مُحَمَّدٍ ﷺ وَآلِهِ وَأَصْحَابِهِ وَأَزْوَاجِهِ وَذُرِّيَّاتِهِ أَجْمَعِينَ، وَإِلَىٰ أَرْوَاحِ سَائِرِ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَالصَّحَابَةِ وَالتَّابِعِينَ وَالْعُلَمَاءِ الْعَامِلِينَ، وَإِلَىٰ أَرْوَاحِ جَمِيعِ أَهْلِ الْقُبُورِ مِنَ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ، خُصُوصًا إِلَىٰ رُوحِ الْمَرْحُومِ / الْمَرْحُومَةِ ........ شَيْءٌ لِلّٰهِ لَهُمُ الْفَاتِحَةُ', rumi: "Ila hadratin-nabiyyil-mustafa Muhammadin sallallahu 'alaihi wa sallam wa alihi wa ashabihi wa azwajihi wa zurriyyatihi ajma'in, wa ila arwahi sa'iril-anbiya'i wal-mursalin wasy-syuhada'i was-salihin was-sahabati wat-tabi'in wal-'ulama'il-'amilin, wa ila arwahi jami'i ahlil-qubur minal-muslimina wal-muslimat wal-mu'minina wal-mu'minat, khususan ila ruhil-marhum / al-marhumah ........ syai'ullahi lahumul-Fatihah.", ms: 'Kepada hadrat Nabi pilihan Muhammad ﷺ, keluarga, para sahabat, isteri-isteri dan zuriat baginda semuanya; kepada roh para nabi dan rasul, para syuhada, orang-orang soleh, para sahabat, tabiin dan ulama yang beramal; kepada roh semua ahli kubur daripada kalangan muslimin, muslimat, mukminin dan mukminat, khususnya roh almarhum / almarhumah (sebut nama). Sedekahkan kepada Allah, Al-Fatihah untuk mereka.', en: 'To the presence of the chosen Prophet Muhammad ﷺ, his family, companions, wives and descendants; to the souls of all prophets and messengers, martyrs, the righteous, the companions, their followers and the practising scholars; to the souls of all Muslims, men and women, believers, men and women, in their graves, especially the soul of the late (say the name). For the sake of Allah, Al-Fatihah for them.' } },
  'Tahlil and Takbir': { m: { ar: 'لَا إِلٰهَ إِلَّا اللهُ، وَاللهُ أَكْبَرُ', rumi: "La ilaha illallah, wallahu akbar.", ms: 'Tiada Tuhan selain Allah, dan Allah Maha Besar.', en: 'There is no god but Allah, and Allah is the Greatest.' } },
  'Selawat upon the Prophet (11×)': { m: { ar: 'اللَّهُمَّ صَلِّ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ وَعَلَىٰ آلِ سَيِّدِنَا مُحَمَّدٍ وَسَلِّمْ', rumi: "Allahumma salli 'ala sayyidina Muhammadin wa 'ala ali sayyidina Muhammadin wa sallim.", ms: 'Ya Allah, limpahkanlah selawat dan salam ke atas penghulu kami Muhammad dan keluarga penghulu kami Muhammad.', en: 'O Allah, send blessings and peace upon our master Muhammad and the family of our master Muhammad.' } },
  'Salam upon the Prophet': { m: { ar: 'السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ', rumi: "Assalamu 'alaika ayyuhan-nabiyyu wa rahmatullahi wa barakatuh.", ms: 'Salam sejahtera ke atas engkau wahai Nabi, serta rahmat Allah dan keberkatan-Nya.', en: 'Peace be upon you, O Prophet, and the mercy of Allah and His blessings.' } },
  'Hauqalah': { m: { ar: 'لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ الْعَلِيِّ الْعَظِيمِ', rumi: "La haula wa la quwwata illa billahil-'aliyyil-'azim.", ms: 'Tiada daya dan tiada kekuatan melainkan dengan Allah Yang Maha Tinggi lagi Maha Agung.', en: 'There is no might and no power except with Allah, the Most High, the Almighty.' } },
  'Istighfar (3×)': { m: { ar: 'أَسْتَغْفِرُ اللهَ الْعَظِيمَ', rumi: "Astaghfirullahal-'azim.", ms: 'Aku memohon ampun kepada Allah Yang Maha Agung.', en: 'I ask forgiveness of Allah the Almighty.' } },
  'Syahadah (La ilaha illallah Muhammadur Rasulullah)': { m: { ar: 'لَا إِلٰهَ إِلَّا اللهُ مُحَمَّدٌ رَسُولُ اللهِ ﷺ', rumi: "La ilaha illallah, Muhammadur-rasulullah sallallahu 'alaihi wa sallam.", ms: 'Tiada Tuhan selain Allah, Muhammad ialah utusan Allah ﷺ.', en: 'There is no god but Allah, Muhammad is the Messenger of Allah ﷺ.' } },
  'Doa Tahlil': { m: { ar: 'اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَشَاهِدِنَا وَغَائِبِنَا وَصَغِيرِنَا وَكَبِيرِنَا وَذَكَرِنَا وَأُنْثَانَا. اللَّهُمَّ اغْفِرْ لَهُمْ وَارْحَمْهُمْ وَعَافِهِمْ وَاعْفُ عَنْهُمْ، وَأَكْرِمْ نُزُلَهُمْ وَوَسِّعْ مُدْخَلَهُمْ، وَاغْسِلْهُمْ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِمْ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ', rumi: "Allahummaghfir lihayyina wa mayyitina wa syahidina wa gha'ibina wa saghirina wa kabirina wa zakarina wa unsana. Allahummaghfir lahum warhamhum wa 'afihim wa'fu 'anhum, wa akrim nuzulahum wa wassi' mudkhalahum, waghsilhum bil-ma'i was-thalji wal-barad, wa naqqihim minal-khataya kama yunaqqath-thaubul-abyadu minad-danas.", ms: 'Ya Allah, ampunilah orang hidup dan orang mati kami, yang hadir dan yang tiada, yang kecil dan yang besar, lelaki dan perempuan kami. Ya Allah, ampunilah mereka, rahmatilah mereka, selamatkanlah mereka dan maafkanlah mereka. Muliakanlah tempat persinggahan mereka, luaskanlah tempat masuk mereka, basuhlah mereka dengan air, salji dan embun, dan bersihkanlah mereka daripada dosa sebagaimana kain putih dibersihkan daripada kotoran.', en: 'O Allah, forgive our living and our dead, those present and absent, young and old, male and female. O Allah, forgive them, have mercy on them, grant them well-being and pardon them. Honour their resting place and make their entrance spacious, wash them with water, snow and hail, and cleanse them of sins as a white garment is cleansed of dirt.' } },
  'Doa Penutup Tahlil': { m: { ar: 'رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ. وَصَلَّى اللهُ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ وَعَلَىٰ آلِهِ وَصَحْبِهِ وَسَلَّمَ، وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ', rumi: "Rabbana atina fid-dunya hasanah wa fil-akhirati hasanah wa qina 'azaban-nar. Wa sallallahu 'ala sayyidina Muhammadin wa 'ala alihi wa sahbihi wa sallam, walhamdu lillahi Rabbil-'alamin.", ms: 'Wahai Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami daripada azab neraka. Semoga Allah mencurahkan selawat dan salam ke atas penghulu kami Muhammad, keluarga dan sahabatnya. Segala puji bagi Allah, Tuhan sekalian alam.', en: 'Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire. May Allah send blessings and peace upon our master Muhammad, his family and companions. All praise is for Allah, Lord of the worlds.' } },
};

// Doa Tahlil Arwah: full doa in the order of the akuislam.com doa images (Arabic from the images; rumi and meaning written for the app). Arwah Lelaki and Arwah Wanita are both shown. To be checked by an ustaz.
ZTEXT['Doa Tahlil'] = { m: { ar: "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيمِ. اَلْحَمْدُ لِلّٰهِ رَبِّ الْعٰلَمِينَ، حَمْدًا يُوَافِي نِعَمَهُ وَيُكَافِئُ مَزِيدَهُ، يَا رَبَّنَا لَكَ الْحَمْدُ كَمَا يَنْبَغِي لِجَلَالِ وَجْهِكَ وَعَظِيمِ سُلْطَانِكَ.", rumi: "Bismillahir-Rahmanir-Rahim. Alhamdu lillahi Rabbil-'alamin, hamdan yuwafi ni'amahu wa yukafi'u mazidah, ya Rabbana lakal-hamdu kama yanbaghi li jalali wajhika wa 'azimi sultanik.", ms: "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang. Segala puji bagi Allah, Tuhan sekalian alam, pujian yang menyamai nikmat-Nya dan menepati tambahan kurnia-Nya. Wahai Tuhan kami, bagi-Mu segala puji sebagaimana layak bagi kemuliaan wajah-Mu dan keagungan kekuasaan-Mu.", en: "In the name of Allah, the Most Gracious, the Most Merciful. All praise is for Allah, Lord of the worlds, a praise that matches His blessings and His increase. Our Lord, to You belongs all praise, as befits the majesty of Your Face and the greatness of Your authority." },
  more: [
  { ar: "اَللّٰهُمَّ صَلِّ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ صَلٰوةً تُنَجِّينَا بِهَا مِنْ جَمِيعِ الْأَهْوَالِ وَالْآفَاتِ، وَتَقْضِي لَنَا بِهَا جَمِيعَ الْحَاجَاتِ.", rumi: "Allahumma salli 'ala sayyidina Muhammadin salatan tunajjina biha min jami'il-ahwali wal-afat, wa taqdi lana biha jami'al-hajat.", ms: "Ya Allah, limpahkanlah selawat ke atas penghulu kami Muhammad, selawat yang dengannya Engkau selamatkan kami daripada segala kegerunan dan bencana, dan Engkau tunaikan untuk kami segala hajat.", en: "O Allah, send blessings upon our master Muhammad, a blessing by which You save us from all terrors and calamities and fulfil all our needs." },
  { ar: "وَتُطَهِّرُنَا بِهَا مِنْ جَمِيعِ السَّيِّئَاتِ، وَتَرْفَعُنَا بِهَا عِنْدَكَ أَعْلَى الدَّرَجَاتِ، وَتُبَلِّغُنَا بِهَا أَقْصَى الْغَايَاتِ، مِنْ جَمِيعِ الْخَيْرَاتِ فِي الْحَيَاةِ وَبَعْدَ الْمَمَاتِ.", rumi: "Wa tutahhiruna biha min jami'is-sayyi'at, wa tarfa'una biha 'indaka a'lad-darajat, wa tuballighuna biha aqsal-ghayat, min jami'il-khayrati fil-hayati wa ba'dal-mamat.", ms: "Dan Engkau sucikan kami dengannya daripada segala kejahatan, Engkau angkat kami dengannya di sisi-Mu ke darjat yang paling tinggi, dan Engkau sampaikan kami dengannya ke puncak segala kebaikan, ketika hidup dan selepas mati.", en: "And by it cleanse us of all evil deeds, raise us in Your sight to the highest ranks, and bring us to the furthest goals of all good, in this life and after death." },
  { ar: "اَللّٰهُمَّ تَقَبَّلْ وَأَوْصِلْ ثَوَابَ مَا قَرَأْنَاهُ مِنَ الْقُرْآنِ الْعَظِيمِ.", rumi: "Allahumma taqabbal wa awsil thawaba ma qara'nahu minal-Qur'anil-'Azim.", ms: "Ya Allah, terimalah dan sampaikanlah pahala apa yang telah kami baca daripada Al-Quran yang agung.", en: "O Allah, accept and let reach the reward of what we have recited from the Great Quran." },
  { ar: "وَمَا اسْتَغْفَرْنَاهُ مِنْ قَوْلِ أَسْتَغْفِرُ اللّٰهَ الْعَظِيمَ. وَمَا هَلَّلْنَاهُ مِنْ قَوْلِ لَا إِلٰهَ إِلَّا اللّٰهُ. وَمَا سَبَّحْنَاهُ مِنْ قَوْلِ سُبْحَانَ اللّٰهِ.", rumi: "Wa mastaghfarnahu min qawli astaghfirullahal-'azim. Wa ma hallalnahu min qawli la ilaha illallah. Wa ma sabbahnahu min qawli subhanallah.", ms: "Dan apa yang kami mohon ampun daripada ucapan Astaghfirullahal-'azim. Dan apa yang kami tahlilkan daripada ucapan La ilaha illallah. Dan apa yang kami tasbihkan daripada ucapan Subhanallah.", en: "And what we sought forgiveness with, from the words Astaghfirullahal-'azim. And what we declared with tahlil, from the words La ilaha illallah. And what we glorified with, from the words Subhanallah." },
  { ar: "وَمَا صَلَّيْنَاهُ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ فِي هٰذَا الْمَجْلِسِ الْمُبَارَكِ هَدِيَّةً مِنَّا وَاصِلَةً وَرَحْمَةً مِنْكَ نَازِلَةً وَبَرَكَةً شَامِلَةً نُهْدِيهَا وَنُقَدِّمُهَا إِلَىٰ حَضْرَةِ النَّبِيِّ مُحَمَّدٍ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ.", rumi: "Wa ma sallaynahu 'ala sayyidina Muhammadin sallallahu 'alayhi wa sallam fi hazal-majlisil-mubarak, hadiyyatan minna wasilatan wa rahmatan minka nazilatan wa barakatan syamilatan, nuhdiha wa nuqaddimuha ila hadratin-nabiyyi Muhammadin sallallahu 'alayhi wa sallam.", ms: "Dan apa yang kami selawatkan ke atas penghulu kami Muhammad SAW dalam majlis yang diberkati ini, sebagai hadiah daripada kami yang sampai, rahmat daripada-Mu yang turun dan berkat yang meliputi, kami hadiahkan dan kami persembahkan ke hadrat Nabi Muhammad SAW.", en: "And the blessings we sent upon our master Muhammad, peace be upon him, in this blessed gathering, as a gift from us that reaches, a mercy from You that descends and a blessing that encompasses, we give and present to the presence of the Prophet Muhammad, peace be upon him." },
  { ar: "ثُمَّ إِلَىٰ جَمِيعِ إِخْوَانِهِ مِنَ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ وَآلِهِ وَأَصْحَابِهِ وَأَزْوَاجِهِ وَذُرِّيَّاتِهِ وَأَهْلِ بَيْتِهِ أَجْمَعِينَ، وَالتَّابِعِينَ وَتَابِعِ التَّابِعِينَ وَالْخُلَفَاءِ الرَّاشِدِينَ وَالْأَئِمَّةِ الْمُجْتَهِدِينَ وَالْأَوْلِيَاءِ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَالْعُلَمَاءِ الْعَامِلِينَ وَجَمِيعِ مَشَايِخِنَا وَأَسَاتِذَتِنَا.", rumi: "Thumma ila jami'i ikhwanihi minal-anbiya'i wal-mursalin, wa alihi wa ashabihi wa azwajihi wa zurriyyatihi wa ahli baytihi ajma'in, wat-tabi'in wa tabi'it-tabi'in, wal-khulafa'ir-rasyidin, wal-a'immatil-mujtahidin, wal-awliya'i wasy-syuhada'i was-salihin, wal-'ulama'il-'amilin, wa jami'i masyayikhina wa asatizatina.", ms: "Kemudian kepada semua saudara baginda daripada kalangan para nabi dan rasul, keluarga baginda, para sahabat, isteri-isteri, zuriat dan ahli bait baginda semuanya, para tabiin dan tabi' tabiin, para khulafa' ar-rasyidin, imam-imam mujtahid, para wali, para syuhada, orang-orang soleh, ulama yang beramal, serta semua guru dan ustaz kami.", en: "Then to all his brothers among the prophets and messengers, his family, companions, wives, descendants and all the people of his house, the Tabi'in and those after them, the rightly guided caliphs, the mujtahid imams, the saints, martyrs and righteous, the scholars who act on their knowledge, and all our teachers and instructors." },
  { ar: "ثُمَّ إِلَىٰ جَمِيعِ أَهْلِ قُبُورٍ مِنَ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ مِنْ مَشَارِقِ الْأَرْضِ وَمَغَارِبِهَا بَرِّهَا وَبَحْرِهَا آبَائِنَا وَأُمَّهَاتِنَا وَأَجْدَادِنَا وَجَدَّاتِنَا وَنَخُصُّ خُصُوصًا مَنِ اجْتَمَعْنَا هُنَا بِسَبَبِهِ وَلِأَجْلِهِ.", rumi: "Thumma ila jami'i ahli qubur minal-muslimina wal-muslimat, wal-mu'minina wal-mu'minat, min masyariqil-ardi wa magharibiha, barriha wa bahriha, aba'ina wa ummahatina wa ajdadina wa jaddatina, wa nakhussu khususan mani jtama'na huna bisababihi wa li ajlih.", ms: "Kemudian kepada semua ahli kubur daripada kalangan Muslimin dan Muslimat, Mukminin dan Mukminat, dari timur dan barat bumi, daratan dan lautannya, bapa-bapa kami, ibu-ibu kami, datuk-datuk kami dan nenek-nenek kami, dan kami khususkan orang yang menjadi sebab dan tujuan kami berhimpun di sini.", en: "Then to all the people of the graves among Muslim men and women and believing men and women, from the east and west of the earth, its land and sea, our fathers, mothers, grandfathers and grandmothers, and specifically the one for whose sake and on whose account we have gathered here." },
  { ar: "وَخُصُوصًا إِلَىٰ رُوحِ الْمَرْحُومِ ................... وَأُصُولِهِ وَفُرُوعِهِ وَمَنْ يَنْتَسِبُ إِلَيْهِ أَجْمَعِينَ.", rumi: "Arwah Lelaki: Wa khususan ila ruhil-marhum ................... wa usulihi wa furu'ihi wa man yantasibu ilayhi ajma'in.", ms: "Arwah Lelaki. Baca nama arwah di ruangan bergaris. Dan khususnya kepada roh almarhum ................... , asal-usulnya, keturunannya dan semua yang bernisbah kepadanya.", en: "Deceased man. Read the name of the deceased in the dotted space. And specifically to the soul of the late ................... , his ancestors, his descendants and all who are related to him." },
  { ar: "وَخُصُوصًا إِلَىٰ رُوحِ الْمَرْحُومَةِ ................... وَأُصُولِهَا وَفُرُوعِهَا وَمَنْ يَنْتَسِبُ إِلَيْهَا أَجْمَعِينَ.", rumi: "Arwah Wanita: Wa khususan ila ruhil-marhumah ................... wa usuliha wa furu'iha wa man yantasibu ilayha ajma'in.", ms: "Arwah Wanita. Baca nama arwah di ruangan bergaris. Dan khususnya kepada roh almarhumah ................... , asal-usulnya, keturunannya dan semua yang bernisbah kepadanya.", en: "Deceased woman. Read the name of the deceased in the dotted space. And specifically to the soul of the late ................... , her ancestors, her descendants and all who are related to her." },
  { ar: "اَللّٰهُمَّ اغْفِرْ لَهُمْ وَارْحَمْهُمْ وَعَافِهِمْ وَاعْفُ عَنْهُمْ", rumi: "Allahummaghfir lahum warhamhum wa 'afihim wa'fu 'anhum. (3×)", ms: "(Baca 3 kali) Ya Allah, ampunilah mereka, rahmatilah mereka, selamatkanlah mereka dan maafkanlah mereka.", en: "(Read 3 times) O Allah, forgive them, have mercy on them, grant them well-being and pardon them." },
  { ar: "اَللّٰهُمَّ اجْعَلْ قُبُورَهُمْ رَوْضَةً مِنْ رِيَاضِ الْجِنَانِ وَلَا تَجْعَلْ قُبُورَهُمْ حُفْرَةً مِنْ حُفَرِ النِّيرَانِ.", rumi: "Allahummaj'al quburahum rawdatan min riyadil-jinan, wa la taj'al quburahum hufratan min hufarin-niran.", ms: "Ya Allah, jadikanlah kubur mereka taman daripada taman-taman syurga, dan janganlah Engkau jadikan kubur mereka lubang daripada lubang-lubang neraka.", en: "O Allah, make their graves a garden from the gardens of Paradise, and do not make their graves a pit from the pits of the Fire." },
  { ar: "اَللّٰهُمَّ بِحَقِّ الْقُرْآنِ الْعَظِيمِ بِجَاهِ كَلَامِكَ الْقَدِيمِ، اجْعَلِ اللّٰهُمَّ ثَوَابَ ذٰلِكَ بَعْدَ الْقَبُولِ فِدَاءً لَهُمْ مِنَ النَّارِ وَسِتْرًا لَهُمْ مِنَ النَّارِ.", rumi: "Allahumma bihaqqil-Qur'anil-'azim, bijahi kalamikal-qadim, ij'alillahumma thawaba zalika ba'dal-qabuli fida'an lahum minan-nar, wa sitran lahum minan-nar.", ms: "Ya Allah, dengan hak Al-Quran yang agung dan kemuliaan kalam-Mu yang qadim, jadikanlah, ya Allah, pahala bacaan itu selepas diterima sebagai tebusan bagi mereka daripada api neraka dan sebagai perisai bagi mereka daripada api neraka.", en: "O Allah, by the right of the Great Quran and the honour of Your eternal Word, make, O Allah, the reward of that, after it is accepted, a ransom for them from the Fire and a shield for them from the Fire." },
  { ar: "اِجْعَلِ اللّٰهُمَّ الْقُرْآنَ يَا اللّٰهُ فِي قُبُورِهِمْ مُؤْنِسًا لَهُمْ وَفِي الْقِيَامَةِ شَافِعًا عَلَى النَّارِ سِتْرًا وَحِجَابًا، وَاجْعَلِ اللّٰهُمَّ الْجَنَّةَ مَأْوَاهُمْ.", rumi: "Ij'alillahummal-Qur'ana ya Allah fi qubur'ihim mu'nisan lahum, wa fil-qiyamati syafi'an 'alan-nari sitran wa hijaba, waj'alillahummal-jannata ma'wahum.", ms: "Ya Allah, jadikanlah Al-Quran, wahai Allah, teman yang menenangkan mereka dalam kubur, dan pemberi syafaat pada hari kiamat, perisai dan dinding daripada api neraka. Dan jadikanlah, ya Allah, syurga tempat tinggal mereka.", en: "O Allah, make the Quran a comforting companion for them in their graves, and an intercessor on the Day of Resurrection, a shield and a barrier against the Fire. And make Paradise their dwelling place." },
  { ar: "اَللّٰهُمَّ أَنْزِلِ الرَّحْمَةَ وَالشَّفَاعَةَ وَالْمَغْفِرَةَ عَلَىٰ جَمِيعِ أَهْلِ قُبُورٍ مِنَ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ، ارْفَعْ لَهُمُ الدَّرَجَاتِ وَضَاعِفْ لَهُمُ الْحَسَنَاتِ وَكَفِّرْ عَنْهُمُ السَّيِّئَاتِ وَأَدْخِلْهُمُ الْجَنَّةَ مَعَ الْآبَاءِ وَالْأُمَّهَاتِ.", rumi: "Allahumma anzilir-rahmata wash-syafa'ata wal-maghfirata 'ala jami'i ahli qubur minal-muslimina wal-muslimat wal-mu'minina wal-mu'minat. Irfa' lahumud-darajat, wa da'if lahumul-hasanat, wa kaffir 'anhumus-sayyi'at, wa adkhilhumul-jannata ma'al-aba'i wal-ummahat.", ms: "Ya Allah, turunkanlah rahmat, syafaat dan keampunan ke atas semua ahli kubur daripada kalangan Muslimin dan Muslimat, Mukminin dan Mukminat. Angkatlah darjat mereka, gandakanlah kebaikan mereka, hapuskanlah kejahatan mereka, dan masukkanlah mereka ke dalam syurga bersama bapa-bapa dan ibu-ibu mereka.", en: "O Allah, send down mercy, intercession and forgiveness upon all the people of the graves among Muslim men and women and believing men and women. Raise their ranks, multiply their good deeds, erase their evil deeds and admit them into Paradise with their fathers and mothers." },
  { ar: "رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ رَبَّنَا إِنَّكَ رَءُوفٌ رَحِيمٌ.", rumi: "Rabbanagh-fir lana wa li-ikhwaninal-lazina sabaquna bil-iman, Rabbana innaka ra'ufur-rahim.", ms: "Wahai Tuhan kami, ampunilah kami dan saudara-saudara kami yang telah mendahului kami dengan iman. Wahai Tuhan kami, sesungguhnya Engkau Maha Penyantun lagi Maha Penyayang.", en: "Our Lord, forgive us and our brothers who preceded us in faith. Our Lord, You are indeed Kind and Merciful." },
  { ar: "يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ، ارْجِعِي إِلَىٰ رَبِّكِ رَاضِيَةً مَرْضِيَّةً، فَادْخُلِي فِي عِبَادِي، وَادْخُلِي جَنَّتِي.", rumi: "Ya ayyatuhan-nafsul-mutma'innah, irji'i ila rabbiki radiyatan mardiyyah, fadkhuli fi 'ibadi, wadkhuli jannati.", ms: "Wahai jiwa yang tenang, kembalilah kepada Tuhanmu dengan hati yang redha dan diredhai. Maka masuklah dalam golongan hamba-hamba-Ku, dan masuklah ke dalam syurga-Ku.", en: "O tranquil soul, return to your Lord, well pleased and pleasing. Enter among My servants, and enter My Paradise." },
  { ar: "رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ. وَصَلَّى اللّٰهُ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ وَعَلَىٰ آلِهِ وَصَحْبِهِ وَسَلَّمَ، سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلَامٌ عَلَى الْمُرْسَلِينَ وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ. الْفَاتِحَةُ.", rumi: "Rabbana atina fid-dunya hasanatan wa fil-akhirati hasanatan wa qina 'azaban-nar. Wa sallallahu 'ala sayyidina Muhammadin wa 'ala alihi wa sahbihi wa sallam. Subhana rabbika rabbil-'izzati 'amma yasifun, wa salamun 'alal-mursalin, wal-hamdu lillahi Rabbil-'alamin. Al-Fatihah.", ms: "Wahai Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami daripada azab neraka. Semoga Allah mencucurkan selawat dan salam ke atas penghulu kami Muhammad, keluarga dan sahabatnya. Maha Suci Tuhanmu, Tuhan Yang Maha Perkasa, daripada apa yang mereka sifatkan. Salam sejahtera ke atas para rasul, dan segala puji bagi Allah, Tuhan sekalian alam. Al-Fatihah.", en: "Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire. May Allah send blessings and peace upon our master Muhammad, his family and companions. Glory to your Lord, the Lord of Might, above what they describe. Peace be upon the messengers, and all praise is for Allah, Lord of the worlds. Al-Fatihah." },
  { ar: "بِسْمِ اللّٰهِ الرَّحْمٰنِ الرَّحِيمِ. الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ. الرَّحْمٰنِ الرَّحِيمِ. مَالِكِ يَوْمِ الدِّينِ. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ. اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ. صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ.", rumi: "Bismillahir-Rahmanir-Rahim. Alhamdu lillahi Rabbil-'alamin. Ar-Rahmanir-Rahim. Maliki yawmid-din. Iyyaka na'budu wa iyyaka nasta'in. Ihdinas-siratal-mustaqim. Siratal-lazina an'amta 'alayhim, ghayril-maghdubi 'alayhim wa lad-dallin.", ms: "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang. Segala puji bagi Allah, Tuhan sekalian alam. Yang Maha Pengasih lagi Maha Penyayang. Yang menguasai hari pembalasan. Hanya Engkau kami sembah dan hanya kepada Engkau kami memohon pertolongan. Tunjukilah kami jalan yang lurus, iaitu jalan orang-orang yang Engkau beri nikmat, bukan jalan mereka yang dimurkai dan bukan jalan mereka yang sesat.", en: "In the name of Allah, the Most Gracious, the Most Merciful. All praise is for Allah, Lord of the worlds. The Most Gracious, the Most Merciful. Master of the Day of Judgement. You alone we worship and You alone we ask for help. Guide us to the straight path, the path of those You have blessed, not of those who earned anger, nor of those who went astray." },
  { ar: "آمِينَ آمِينَ آمِينَ يَا رَبَّ الْعَالَمِينَ، رَبَّنَا تَقَبَّلْ مِنَّا دُعَاءَنَا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ، وَتُبْ عَلَيْنَا يَا مَوْلَانَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ، وَلَا تُؤَاخِذْنَا بِالْعَظَائِمِ وَالْجَرَائِمِ يَا كَرِيمُ، وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ. تَقَبَّلَ اللّٰهُ مِنَّا وَمِنْكُمْ. (تَقَبَّلْ مِنَّا يَا كَرِيمُ)", rumi: "Amin, amin, amin ya Rabbal-'alamin. Rabbana taqabbal minna du'a'ana innaka antas-Sami'ul-'Alim, wa tub 'alayna ya mawlana innaka antat-Tawwabur-Rahim, wa la tu'akhizna bil-'aza'imi wal-jara'imi ya Karim. Wa akhiru da'wana anil-hamdu lillahi Rabbil-'alamin. Taqabbalallahu minna wa minkum. (Taqabbal minna ya Karim)", ms: "Amin, amin, amin, wahai Tuhan sekalian alam. Wahai Tuhan kami, terimalah doa kami, sesungguhnya Engkau Maha Mendengar lagi Maha Mengetahui. Terimalah taubat kami, wahai Pelindung kami, sesungguhnya Engkau Maha Penerima taubat lagi Maha Penyayang. Janganlah Engkau hukum kami atas dosa-dosa besar dan kejahatan, wahai Yang Maha Pemurah. Penutup doa kami ialah segala puji bagi Allah, Tuhan sekalian alam. Semoga Allah menerima amalan daripada kami dan kamu. (Terimalah daripada kami, wahai Yang Maha Pemurah)", en: "Amen, amen, amen, O Lord of the worlds. Our Lord, accept our prayer, You are the All-Hearing, the All-Knowing. Accept our repentance, O our Protector, You are the Accepter of repentance, the Merciful. Do not hold us to account for great sins and crimes, O Generous One. The end of our prayer is that all praise is for Allah, Lord of the worlds. May Allah accept from us and from you. (Accept from us, O Generous One)" }] };

ZTEXT['Doa: Allahumma bika asbahna / amsayna'] = {
  m: { ar: 'اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ', rumi: "Allahumma bika asbahna, wa bika amsayna, wa bika nahya, wa bika namutu, wa ilaikan-nusyur.", ms: 'Ya Allah, dengan-Mu kami memasuki pagi, dengan-Mu kami memasuki petang, dengan-Mu kami hidup, dengan-Mu kami mati, dan kepada-Mu kami dibangkitkan.', en: 'O Allah, by You we enter the morning, by You we enter the evening, by You we live, by You we die, and to You is the resurrection.' },
  e: { ar: 'اللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ', rumi: "Allahumma bika amsayna, wa bika asbahna, wa bika nahya, wa bika namutu, wa ilaikal-masir.", ms: 'Ya Allah, dengan-Mu kami memasuki petang, dengan-Mu kami memasuki pagi, dengan-Mu kami hidup, dengan-Mu kami mati, dan kepada-Mu tempat kembali.', en: 'O Allah, by You we enter the evening, by You we enter the morning, by You we live, by You we die, and to You is the final return.' } };

ZTEXT['Doa Rabithah'] = { m: {
  ar: 'اللَّهُمَّ إِنَّكَ تَعْلَمُ أَنَّ هَذِهِ الْقُلُوبَ قَدِ اجْتَمَعَتْ عَلَىٰ مَحَبَّتِكَ، وَالْتَقَتْ عَلَىٰ طَاعَتِكَ، وَتَوَحَّدَتْ عَلَىٰ دَعْوَتِكَ، وَتَعَاهَدَتْ عَلَىٰ نُصْرَةِ شَرِيعَتِكَ. فَوَثِّقِ اللَّهُمَّ رَابِطَتَهَا، وَأَدِمْ وُدَّهَا، وَاهْدِهَا سُبُلَهَا، وَامْلَأْهَا بِنُورِكَ الَّذِي لَا يَخْبُو، وَاشْرَحْ صُدُورَهَا بِفَيْضِ الْإِيمَانِ بِكَ وَجَمِيلِ التَّوَكُّلِ عَلَيْكَ، وَأَحْيِهَا بِمَعْرِفَتِكَ، وَأَمِتْهَا عَلَىٰ الشَّهَادَةِ فِي سَبِيلِكَ. إِنَّكَ نِعْمَ الْمَوْلَىٰ وَنِعْمَ النَّصِيرُ',
  rumi: "Allahumma innaka ta'lamu anna hazihil-qulub, qadij-tama'at 'ala mahabbatik, wal-taqat 'ala ta'atik, wa tawahhadat 'ala da'watik, wa ta'ahadat 'ala nusrati syari'atik. Fawaththiqil-lahumma rabithataha, wa adim wuddaha, wahdiha subulaha, wamla'ha binurikal-lazi la yakhbu, wasyrah suduraha bifaidil-imani bik, wa jamilit-tawakkuli 'alaik, wa ahyiha bima'rifatik, wa amithaha 'alasy-syahadati fi sabilik. Innaka ni'mal-maula wa ni'man-nasir.",
  ms: 'Ya Allah, Engkau mengetahui bahawa hati-hati ini telah berhimpun atas kasih-Mu, bertemu atas ketaatan kepada-Mu, bersatu atas dakwah-Mu dan berjanji untuk membela syariat-Mu. Maka eratkanlah ikatannya, kekalkanlah kasih sayangnya, tunjukkanlah jalan-jalannya, penuhilah ia dengan cahaya-Mu yang tidak pernah padam, lapangkanlah dada-dadanya dengan limpahan iman kepada-Mu dan tawakal yang indah kepada-Mu, hidupkanlah ia dengan mengenal-Mu dan matikanlah ia dalam syahid di jalan-Mu. Sesungguhnya Engkau sebaik-baik pelindung dan sebaik-baik penolong.',
  en: 'O Allah, You know that these hearts have gathered in love for You, met in obedience to You, united in calling to You and pledged to support Your law. So strengthen their bond, make their affection last, guide them to their paths, fill them with Your light that never fades, expand their chests with the abundance of faith in You and beautiful reliance upon You, give them life through knowing You, and let them die as martyrs in Your way. Indeed You are the best Protector and the best Helper.' } };

ZTEXT["Doa Penutup Al-Ma'thurat"] = { m: {
  ar: 'سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ، وَسَلَامٌ عَلَى الْمُرْسَلِينَ، وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ. اللَّهُمَّ صَلِّ وَسَلِّمْ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ وَعَلَىٰ آلِهِ وَصَحْبِهِ أَجْمَعِينَ',
  rumi: "Subhana Rabbika Rabbil-'izzati 'amma yasifun, wa salamun 'alal-mursalin, walhamdu lillahi Rabbil-'alamin. Allahumma salli wa sallim 'ala sayyidina Muhammadin wa 'ala alihi wa sahbihi ajma'in.",
  ms: 'Maha Suci Tuhanmu, Tuhan Yang Maha Perkasa, daripada apa yang mereka sifatkan. Salam sejahtera ke atas para rasul. Segala puji bagi Allah, Tuhan sekalian alam. Ya Allah, limpahkanlah selawat dan salam ke atas penghulu kami Muhammad, keluarga dan seluruh sahabatnya.',
  en: 'Glory to your Lord, the Lord of Might, above what they describe. Peace be upon the messengers. All praise is for Allah, Lord of the worlds. O Allah, send blessings and peace upon our master Muhammad, his family and all his companions.' } };

// Doa after Surah Yasin: the full Doa Yasin (Arabic text from the akuislam.com doa image; rumi and meaning written for the app). To be checked by an ustaz.
ZTEXT['Doa after Yasin'] = { m: { ar: "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيمِ. اَلْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ حَمْدًا يُوَافِي نِعَمَهُ وَيُكَافِئُ مَزِيدَهُ، يَا رَبَّنَا لَكَ الْحَمْدُ كَمَا يَنْبَغِي لِجَلَالِ وَجْهِكَ وَعَظِيمِ سُلْطَانِكَ.", rumi: "Bismillahir-Rahmanir-Rahim. Alhamdu lillahi Rabbil-'alamin, hamdan yuwafi ni'amahu wa yukafi'u mazidah. Ya Rabbana lakal-hamdu kama yanbaghi li jalali wajhika wa 'azimi sultanik.", ms: "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang. Segala puji bagi Allah, Tuhan sekalian alam, pujian yang menyamai nikmat-Nya dan menepati tambahan kurnia-Nya. Wahai Tuhan kami, bagi-Mu segala puji sebagaimana layak bagi kemuliaan wajah-Mu dan keagungan kekuasaan-Mu.", en: "In the name of Allah, the Most Gracious, the Most Merciful. All praise is for Allah, Lord of the worlds, a praise that matches His blessings and His increase. Our Lord, to You belongs all praise, as befits the majesty of Your Face and the greatness of Your authority." },
  more: [
  { ar: "اَللّٰهُمَّ صَلِّ وَسَلِّمْ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ وَعَلَىٰ آلِهِ وَصَحْبِهِ أَجْمَعِينَ.", rumi: "Allahumma salli wa sallim 'ala sayyidina Muhammadin wa 'ala alihi wa sahbihi ajma'in.", ms: "Ya Allah, limpahkanlah selawat dan salam ke atas penghulu kami Muhammad, keluarga dan seluruh sahabatnya.", en: "O Allah, send blessings and peace upon our master Muhammad, his family and all his companions." },
  { ar: "اَللّٰهُمَّ بِحَقِّ يٰسٓ وَالْقُرْآنِ الْحَكِيمِ وَبِمَنِ اخْتَرْتَهُ بِالرِّسَالَةِ وَالنُّبُوَّةِ وَالْوِلَايَةِ وَالْهِدَايَةِ إِلَىٰ صِرَاطِكَ الْمُسْتَقِيمِ.", rumi: "Allahumma bihaqqi Ya Sin wal-Qur'anil-Hakim, wa biman akhtartahu bir-risalati wan-nubuwwati wal-wilayati wal-hidayati ila siratikal-mustaqim.", ms: "Ya Allah, dengan hak Yasin dan Al-Quran yang penuh hikmah, dan dengan hak orang yang Engkau pilih untuk risalah, kenabian, kewalian dan hidayah menuju jalan-Mu yang lurus.", en: "O Allah, by the right of Ya Sin and the Wise Quran, and by those You chose for the message, prophethood, sainthood and guidance to Your straight path." },
  { ar: "وَبِجَمِيعِ مَا جَاءَ بِهِ مِنْكَ جِبْرِيلُ، تَنْزِيلَ الْعَزِيزِ الرَّحِيمِ، وَبِخَوَاصِّ الْحُرُوفِ وَالْأَسْمَاءِ التَّامَّاتِ، وَبِمَا أَظْهَرْتَ فِي الْوُجُودِ لِكُلِّ مَوْجُودٍ مِنَ الْآيَاتِ الْبَيِّنَاتِ.", rumi: "Wa bijami'i ma ja'a bihi minka Jibrilu, tanzilal-'Azizir-Rahim, wa bikhawassil-huruf wal-asma'it-tammat, wa bima azharta fil-wujudi likulli mawjudin minal-ayatil-bayyinat.", ms: "Dan dengan segala yang dibawa oleh Jibril daripada-Mu, wahyu daripada Yang Maha Perkasa lagi Maha Penyayang, dengan kekhususan huruf-huruf dan nama-nama-Mu yang sempurna, dan dengan segala tanda yang jelas yang Engkau zahirkan dalam kewujudan bagi setiap yang wujud.", en: "And by all that Jibril brought from You, a revelation from the Almighty, the Merciful, by the special virtues of the letters and Your perfect names, and by the clear signs You have shown in existence to everything that exists." },
  { ar: "وَبِخَفِيِّ لُطْفِكَ الْمُفَرِّجِ عَنْ كُلِّ مَهْمُومٍ، الْمُخَلِّصِ لِكُلِّ مَدْيُونٍ، يَا مُجْرِيَ الْبِحَارِ وَالْعُيُونِ، يَا مَنْ خَزَائِنُهُ بَيْنَ الْكَافِ وَالنُّونِ، وَعِلْمٍ بِمَا كَانَ قَبْلَ أَنْ يَكُونَ.", rumi: "Wa bikhafiyyi lutfikal-mufarrijil 'an kulli mahmum, al-mukhallisi likulli madyun, ya mujriyal-bihari wal-'uyun, ya man khaza'inuhu baynal-kafi wan-nun, wa 'ilmin bima kana qabla an yakun.", ms: "Dan dengan kelembutan-Mu yang tersembunyi yang melapangkan setiap orang yang bersusah hati dan membebaskan setiap orang yang berhutang. Wahai Yang mengalirkan lautan dan mata air, wahai Yang perbendaharaan-Nya di antara huruf Kaf dan Nun, dan Yang mengetahui apa yang terjadi sebelum ia terjadi.", en: "And by Your hidden kindness that relieves every worried person and frees every debtor. O You who make the seas and springs flow, O You whose treasures lie between Kaf and Nun, and who knows what will be before it is." },
  { ar: "وَنَسْأَلُكَ اللّٰهُمَّ أَنْ تَسْئَلُكَ بِنَا جَادَّةَ رِضَاكَ، وَأَنْ تَجْعَلَنَا أَهْلًا وَمَحَلًّا لِسَعَادَتِكَ وَغِنَاكَ، وَأَنْ تُيَسِّرَ لَنَا جَمِيعَ الْمُرَادَاتِ وَالْمَطَالِبِ، وَأَنْ تَجْعَلَ رِضَاكَ عَنَّا خَيْرَ مُصَاحِبٍ لَنَا وَرَفِيقٍ، وَأَنْ تُتْحِفَنَا بِالْجَلَالَةِ وَالْمَهَابَةِ، وَأَنْ تَمُنَّ عَلَيْنَا بِسُرْعَةِ الْإِجَابَةِ.", rumi: "Wa nas'aluka Allahumma an tas'aluka bina jaddata ridak, wa an taj'alana ahlan wa mahallan lisa'adatika wa ghinak, wa an tuyassira lana jami'al-muradati wal-matalib, wa an taj'ala ridaka 'anna khayra musahibin lana wa rafiq, wa an tuthhifana bil-jalalati wal-mahabah, wa an tumanna 'alayna bisur'atil-ijabah.", ms: "Dan kami memohon kepada-Mu, ya Allah, agar Engkau membawa kami menempuh jalan keredaan-Mu, menjadikan kami layak dan tempat bagi kebahagiaan dan kekayaan-Mu, memudahkan bagi kami segala hajat dan keperluan, menjadikan keredaan-Mu kepada kami sebaik-baik pengiring dan teman, mengurniakan kami kemuliaan dan kewibawaan, dan memberi kami nikmat doa yang cepat dimakbulkan.", en: "And we ask You, O Allah, to guide us along the path of Your pleasure, to make us fit for and a place of Your happiness and richness, to ease all our wishes and needs, to make Your pleasure with us our best companion, to grant us dignity and awe, and to favour us with a swift answer." },
  { ar: "اِسْتَجِبِ اللّٰهُمَّ دُعَاءَنَا، وَحَقِّقْ فِيكَ رَجَاءَنَا، وَادْخِلْنَا فِي حِرْزِ لُطْفِكَ الْمَصُونِ بِسِرِّ قَوْلِكَ: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ، فَسُبْحَانَ الَّذِي بِيَدِهِ مَلَكُوتُ كُلِّ شَيْءٍ وَإِلَيْهِ تُرْجَعُونَ.", rumi: "Istajibillahumma du'a'ana, wa haqqiq fika raja'ana, wadkhilna fi hirzi lutfikal-masun, bisirri qawlika: innama amruhu iza arada syai'an an yaqula lahu kun fayakun, fasubhanal-lazi biyadihi malakutu kulli syai'in wa ilayhi turja'un.", ms: "Perkenankanlah, ya Allah, doa kami, tunaikanlah harapan kami kepada-Mu, dan masukkanlah kami ke dalam perlindungan kelembutan-Mu yang terpelihara, dengan rahsia firman-Mu: \"Sesungguhnya urusan-Nya apabila Dia menghendaki sesuatu, Dia hanya berfirman kepadanya: Jadilah! Maka jadilah ia.\" Maha Suci Allah yang di tangan-Nya kekuasaan atas segala sesuatu, dan kepada-Nya kamu dikembalikan.", en: "Answer our prayer, O Allah, fulfil our hope in You, and admit us into the guarded shelter of Your kindness, by the secret of Your words: \"His command, when He wills a thing, is only to say to it: Be! and it is.\" So glory be to Him in whose hand is the dominion of all things, and to Him you will be returned." },
  { ar: "سُبْحَانَ الْمُنَفِّسِ عَنْ كُلِّ مَهْمُومٍ، سُبْحَانَ الْمُنَفِّسِ عَنْ كُلِّ مَدْيُونٍ، سُبْحَانَ مَنْ أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ.", rumi: "Subhanal-munaffisi 'an kulli mahmum, subhanal-munaffisi 'an kulli madyun, subhana man amruhu iza arada syai'an an yaqula lahu kun fayakun.", ms: "Maha Suci Allah yang melapangkan setiap orang yang bersusah hati, Maha Suci Allah yang melapangkan setiap orang yang berhutang, Maha Suci Allah yang urusan-Nya apabila menghendaki sesuatu hanya berfirman: Jadilah! Maka jadilah ia.", en: "Glory be to the One who relieves every worried person, glory be to the One who relieves every debtor, glory be to the One whose command, when He wills a thing, is only to say: Be! and it is." },
  { ar: "يَا مُفَرِّجَ الْهُمُومِ، يَا مُفَرِّجُ فَرِّجْ، يَا مُفَرِّجُ فَرِّجْ، فَرِّجْ عَنَّا هُمُومَنَا يَا حَيُّ يَا قَيُّومُ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، وَصَلَّى اللهُ عَلَىٰ سَيِّدِنَا مُحَمَّدٍ وَعَلَىٰ آلِهِ وَصَحْبِهِ وَسَلَّمَ، وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِينَ.", rumi: "Ya mufarrijal-humum, ya mufarriju farrij, ya mufarriju farrij, farrij 'anna humumana ya Hayyu ya Qayyum, ya Zal-Jalali wal-Ikram, wa sallallahu 'ala sayyidina Muhammadin wa 'ala alihi wa sahbihi wa sallam, wal-hamdu lillahi Rabbil-'alamin.", ms: "Wahai Yang melapangkan segala kesusahan, wahai Yang melapangkan, lapangkanlah, wahai Yang melapangkan, lapangkanlah. Lapangkanlah kesusahan kami, wahai Yang Hidup, wahai Yang Berdiri Sendiri, wahai Pemilik Kebesaran dan Kemuliaan. Semoga Allah mencucurkan selawat dan salam ke atas penghulu kami Muhammad, keluarga dan sahabatnya, dan segala puji bagi Allah, Tuhan sekalian alam.", en: "O Reliever of all worries, O Reliever, relieve us, O Reliever, relieve us. Relieve us of our worries, O Ever-Living, O Sustainer, O Lord of Majesty and Honour. May Allah send blessings and peace upon our master Muhammad, his family and companions, and all praise is for Allah, Lord of the worlds." }] };
